import com.fasterxml.jackson.databind.ObjectMapper
import org.springframework.data.redis.core.RedisTemplate
import org.springframework.stereotype.Component
import java.time.Duration

@Component
class TieredCacheFactory(
    private val redisTemplate: RedisTemplate<String, String>,
    private val objectMapper: ObjectMapper,
) {
    fun <ID : Any, V : Any> create(
        type: Class<V>,
        idExtractor: (V) -> ID,
        keyPrefix: String,
        l1Ttl: Duration,
        l2Ttl: Duration,
        maxSize: Long,
    ): TieredCache<ID, V> {
        val l1 = CaffeineLocalCache<ID, V>(ttl = l1Ttl, maxSize = maxSize)
        val serializer = JacksonCacheSerializer(objectMapper, type)
        val l2 = ValkeyRemoteCache<ID, V>(redisTemplate, serializer, keyPrefix, l2Ttl)
        return TieredCacheImpl(l1, l2, idExtractor)
    }
}"}

